# ruff: noqa: E501  (glossary sentences read better unbroken)
"""The glossary behind every number: two depths, three languages.

One entry per `Metric` a Claim can carry. Each has a fan line (the meaning first, no jargon), an
analyst definition (names the metric and how it is counted), why it matters, and the "?" help
text in English, Spanish and Catalan. `kinds` lists the insight kinds whose claims use it (a test
checks that no insight uses a metric that is not listed here).

`docs/METRICS.md` is generated from this file: `python -m whyitmatters.pulse.glossary --write`.
Definitions and sources are in docs/METHODS.md; this is the wording shown to viewers.
"""

from __future__ import annotations

import sys
from pathlib import Path
from typing import NamedTuple


